mapper.select:
SELECT EXISTS (SELECT 1 FROM TB_SY_CHG_HIST h
  WHERE upper(h.trgt_tbl_nm)=#{ref.table}
    AND (upper(h.chg_item_nm)=#{ref.column} OR h.chg_item_nm=#{row.groupId})
    AND (h.bfr_val=#{row.code} OR h.aft_val=#{row.code}

        OR h.bfr_val=#{row.codeName} OR h.aft_val=#{row.codeName}
        OR h.bfr_val IN (SELECT n.bfr_val FROM TB_SY_CHG_HIST n WHERE n.trgt_tbl_nm='TB_SY_CODE'
          AND n.trgt_key=#{row.groupId} || ':' || #{row.code} AND n.chg_item_nm='CODE_NM')
        OR h.aft_val IN (SELECT n.bfr_val FROM TB_SY_CHG_HIST n WHERE n.trgt_tbl_nm='TB_SY_CODE'
          AND n.trgt_key=#{row.groupId} || ':' || #{row.code} AND n.chg_item_nm='CODE_NM')
      ))

  OR EXISTS (SELECT 1 FROM TB_SY_CHG_HIST h WHERE h.trgt_tbl_nm='TB_PJ_ASGN_HIST'
    AND h.chg_item_nm=#{row.groupId} AND (h.bfr_val=#{row.code} OR h.aft_val=#{row.code}))
